"use client";
import { gmailPauseMessage } from "@/lib/gmail-pause";
import { useState } from "react";
import { usePathname } from "next/navigation";
import { LimitBanner } from "./limit-banner";
import { refreshWorkspaceAccess } from "@/components/workspace-quota";
import Link from "next/link";
import { DateTime } from "@/components/date-time";
import {
  useWorkspaceEntitlements,
  useWorkspaceQuota,
} from "@/components/workspace-quota";
import { SUPPORT_EMAIL } from "@/lib/pricing";

function AccessBanners() {
  const pathname = usePathname();
  const showDailyLimit = pathname === "/compose" || pathname === "/usage";
  const access = useWorkspaceEntitlements();
  const quota = useWorkspaceQuota();
  const reason = access.reasons.send;
  if (reason === "ACCOUNT_SUSPENDED")
    return (
      <div
        role="status"
        className="usage-notice [border-left:3px_solid_var(--accent)] py-3 px-4.5 my-6 text-[14px] leading-[24px] mb-6 space-y-2 text-sm text-warning"
      >
        <p>
          Your account is suspended. Sending paused; paid features are
          unavailable. Suspension does not cancel billing.
        </p>
        <p>
          <Link href="/usage" className="text-link underline">
            Manage or cancel subscription
          </Link>
          {" · "}
          <Link href="/settings" className="text-link underline">
            Export data or delete your account
          </Link>
          {" · "}
          <a className="text-link underline" href={`mailto:${SUPPORT_EMAIL}`}>
            Contact support
          </a>
        </p>
      </div>
    );
  if (access.gmailPause)
    return (
      <div
        role="status"
        className="usage-notice [border-left:3px_solid_var(--accent)] py-3 px-4.5 my-6 text-[14px] leading-[24px] mb-6 space-y-2 text-sm text-warning"
      >
        <p>{gmailPauseMessage(access.gmailPause)}</p>
        {access.gmailPause.until && (
          <p>
            Provider cooldown until <DateTime value={access.gmailPause.until} />
            .
          </p>
        )}
        <Link href="/settings" className="text-link underline">
          {["RECONNECT_REQUIRED", "DOMAIN_POLICY"].includes(
            access.gmailPause.code,
          )
            ? "Reconnect Gmail"
            : "Review Gmail status"}
        </Link>
      </div>
    );
  const exhausted =
    quota.mode === "gated"
      ? [quota.daily, quota.monthly].filter(
          (value) => value.startsAt && value.used >= value.limit,
        )
      : [];
  const legacyExhausted = quota.mode === "legacy" && quota.used >= quota.limit;
  if (
    !access.features.send ||
    (quota.mode === "gated" && !quota.sendingAllowed)
  )
    return (
      <div
        role="status"
        className="usage-notice [border-left:3px_solid_var(--accent)] py-3 px-4.5 my-6 text-[14px] leading-[24px] mb-6 text-sm text-warning"
      >
        <p>
          Sending paused.{" "}
          {quota.mode === "gated"
            ? quota.pauseReason
            : reason === "GMAIL_RECONNECT_REQUIRED"
              ? "Reconnect Gmail in Settings before sending."
              : "Sending is temporarily unavailable. Try again shortly or contact support."}{" "}
          <Link
            href={
              reason === "BILLING_PERIOD_UNRESOLVED" ? "/usage" : "/settings"
            }
            className="text-link underline"
          >
            {reason === "BILLING_PERIOD_UNRESOLVED"
              ? "Review Usage"
              : "Open Settings"}
          </Link>
          {" · "}
          <a href={`mailto:${SUPPORT_EMAIL}`} className="text-link underline">
            Contact support
          </a>
        </p>
      </div>
    );
  if (!exhausted.length && !legacyExhausted) return null;
  const daily = quota.mode === "gated" ? quota.daily : null;
  const monthly = quota.mode === "gated" ? quota.monthly : null;
  return (
    <>
      {showDailyLimit &&
        daily?.startsAt &&
        daily.used >= daily.limit &&
        daily.resetsAt && (
          <LimitBanner
            used={daily.used}
            limit={daily.limit}
            resetAt={daily.resetsAt}
            upgradeHref="/usage"
            allowancesHref="/usage#allowances"
          />
        )}
      {quota.mode === "gated" &&
        [
          ["Daily", daily],
          ["Monthly", monthly],
        ].map(([label, value]) => {
          if (
            !value ||
            typeof value === "string" ||
            !value.startsAt ||
            value.used < value.limit ||
            (label === "Daily" && value.resetsAt)
          )
            return null;
          return (
            <div
              key={String(label)}
              role="status"
              className="usage-notice [border-left:3px_solid_var(--accent)] py-3 px-4.5 my-6 text-[14px] leading-[24px] mb-6 text-sm text-body"
            >
              <p>
                {String(label)} allowance reached: {value.used} of {value.limit}{" "}
                emails used, including queued emails.{" "}
                {value.resetsAt ? (
                  <>
                    Resets <DateTime value={value.resetsAt} /> (your time).{" "}
                  </>
                ) : (
                  "Reset awaits verified billing dates. "
                )}
                <Link href="/usage#allowances" className="text-link underline">
                  View allowances &amp; reset times
                </Link>
              </p>
            </div>
          );
        })}
      {legacyExhausted && (
        <div
          role="status"
          className="usage-notice [border-left:3px_solid_var(--accent)] py-3 px-4.5 my-6 text-[14px] leading-[24px] mb-6 text-sm text-body"
        >
          <p>
            Sending allowance reached. Capacity returns as sends leave the
            rolling 24-hour window or unused queue reservations are released.{" "}
            <Link href="/usage#allowances" className="text-link underline">
              View allowances &amp; reset times
            </Link>
          </p>
        </div>
      )}
    </>
  );
}

export function WorkspaceBanners() {
  const quota = useWorkspaceQuota();
  const [pending, setPending] = useState<string | null>(null);
  const [error, setError] = useState(false);
  async function dismiss(noticeId: string) {
    setPending(noticeId);
    setError(false);
    try {
      const response = await fetch("/api/account/notices", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ noticeId }),
      });
      if (!response.ok) throw new Error("Dismissal failed");
      refreshWorkspaceAccess();
    } catch {
      setError(true);
    } finally {
      setPending(null);
    }
  }
  const reasons: Record<string, string> = {
    FREE_ALLOWANCE:
      "The complete unsent remainder exceeded your Free allowance.",
    FREE_RECIPIENT_LIMIT:
      "The original campaign exceeded the Free recipient limit.",
    FREE_TEMPLATE: "The campaign used a template outside your Free selection.",
    FREE_CUSTOM_ROLE:
      "The campaign was cancelled under the previous custom-role policy. Existing custom roles can now be used on either plan.",
    FREE_REPEAT_SEND:
      "The campaign repeated a previous email, which requires Paid.",
  };
  return (
    <>
      {quota.notices?.map((notice) => (
        <div
          key={notice.id}
          role="status"
          className="usage-notice [border-left:3px_solid_var(--accent)] py-3 px-4.5 my-6 text-[14px] leading-[24px] mb-6 space-y-2 text-sm text-body"
        >
          <p>
            {notice.cancelledCount} queued{" "}
            {notice.cancelledCount === 1 ? "email was" : "emails were"}{" "}
            cancelled.{" "}
            {reasons[notice.reasonCode] ??
              "The campaign exceeded your current plan."}{" "}
            Cancelled emails stay cancelled if you upgrade.
          </p>
          <p>
            <Link href="/history" className="text-link underline">
              Review campaign history
            </Link>
            {" · "}
            <button
              type="button"
              className="text-link underline"
              disabled={pending === notice.id}
              onClick={() => void dismiss(notice.id)}
            >
              {pending === notice.id ? "Dismissing…" : "Dismiss notice"}
            </button>
          </p>
        </div>
      ))}
      {error && (
        <p role="alert" className="mb-4 text-sm text-warning">
          The notice could not be dismissed. Try again.
        </p>
      )}
      <AccessBanners />
    </>
  );
}
